#include "stock_native_client_critical.hpp"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace stock_native_client_critical {
namespace {
using V=shared::Value;using Device=wot::offline_bot_step::Device;
V object(){V v;v.kind=V::Kind::Object;return v;}
V array(){V v;v.kind=V::Kind::Array;return v;}
V number(double n){V v;v.kind=V::Kind::Number;v.number=n;return v;}
V integer(std::int64_t n){V v;v.kind=V::Kind::Integer;v.integer=n;return v;}
V boolean(bool n){V v;v.kind=V::Kind::Boolean;v.boolean=n;return v;}
V text(const std::string&n){V v;v.kind=V::Kind::Text;v.text=n;return v;}
V names(const std::set<std::string>&values){auto out=array();for(const auto&n:values)out.array.push_back(text(n));return out;}
bool track(const std::string&n){return n=="leftTrackHealth"||n=="rightTrackHealth";}
void mergeTracks(const Critical&source,Critical&target){for(const char*name:{"leftTrackHealth","rightTrackHealth"}){const auto from=source.devices.find(name);if(from==source.devices.end())continue;auto&to=target.devices[name];to.hp=from->second.hp;to.destroyed=from->second.destroyed;to.critical=from->second.critical;}}
std::string deviceState(const Device&d){if(d.destroyed)return "destroyed";if(d.critical)return "critical";if(!d.hp||*d.hp<=0.)return "destroyed";if(d.maximum&&*d.hp<=*d.maximum*.5)return "critical";return "normal";}
std::string payloadState(Device device,const std::string&name,const Metadata&metadata){
 // _state first projects the accepted descriptor's yellow threshold; the
 // later _payload record uses the actual mounted descriptor's HP pool.
 if(!device.destroyed&&device.hp&&*device.hp>0.&&device.maximum&&*device.hp<=*device.maximum*.5)device.critical=true;
 const auto maximum=metadata.maxima.find(name);if(maximum!=metadata.maxima.end())device.maximum=maximum->second;
 return deviceState(device);
}
double decimal(double value){
 if(value==0.)return value;int exponent=0;const auto mantissa=std::uint64_t(std::ldexp(std::frexp(std::abs(value),&exponent),53));const std::uint64_t factor=125,upper=(mantissa>>32)*factor,lower=(mantissa&0xffffffffULL)*factor,low=lower+(upper<<32),high=(upper>>32)+(low<lower);const int shift=53-exponent-3;std::uint64_t quotient=0;bool half=false;if(shift<=0)throw std::invalid_argument("Native repair checkpoint rounding overflow");if(shift<64){quotient=(low>>shift)|(high<<(64-shift));half=((low>>(shift-1))&1)!=0;}else if(shift==64){quotient=high;half=(low>>63)!=0;}else if(shift<128){quotient=high>>(shift-64);half=((high>>(shift-65))&1)!=0;}else if(shift==128)half=(high>>63)!=0;if(half)++quotient;return std::copysign(double(quotient)/1000.,value);
}
double seconds(const std::string&name,double repair,double misc){double factor=std::max(0.,repair)/.57;factor*=misc;if(factor<=0.)factor=1.;return (name.find("Track")!=std::string::npos||name.find("track")!=std::string::npos?12.:21.6)/factor;}
V payload(const Critical&before,const Critical&after,const Metadata&metadata,const std::set<std::string>&casualties){auto out=object(),devices=array(),events=array();std::set<std::string>destroyed;for(const auto&row:after.devices){const auto&name=row.first;const auto&d=row.second;if(!d.hp&&!d.destroyed&&!d.critical)continue;const double hp=std::max(0.,d.hp.value_or(0.));const auto pool=metadata.maxima.find(name);const double maximum=std::max(1.,pool==metadata.maxima.end()?double(std::round(hp)):pool->second);auto value=object();value.object["name"]=text(name);value.object["hp"]=number(hp);value.object["max_hp"]=number(maximum);value.object["state"]=text(payloadState(d,name,metadata));devices.array.push_back(std::move(value));if(d.destroyed)destroyed.insert(name);const auto prior=before.devices.find(name);const auto old=prior==before.devices.end()||!prior->second.hp?"normal":payloadState(prior->second,name,metadata);const auto current=payloadState(d,name,metadata);if(old!=current){auto event=object();event.object["kind"]=text("device");event.object["name"]=text(name);event.object["old_state"]=text(old);event.object["state"]=text(current);event.object["cause"]=text("repair");events.array.push_back(std::move(event));}}
 out.object["devices"]=std::move(devices);out.object["destroyed"]=names(destroyed);out.object["crew_ko"]=names(casualties);out.object["fire"]=boolean(after.fire);out.object["ammo_rack_death"]=boolean(after.ammo_rack_death);out.object["events"]=std::move(events);return out;}
void progress(const Critical&current,const Metadata&metadata,double repair,State&state,std::vector<Progress>&out){std::set<std::string>destroyed;for(const auto&row:current.devices){const auto&name=row.first;const auto&d=row.second;if(!d.destroyed)continue;destroyed.insert(name);if(name=="fuelTankHealth")continue;const auto pool=metadata.regeneration.find(name);if(pool==metadata.regeneration.end()||pool->second==0.)continue;const double cap=pool->second,hp=std::max(0.,std::min(d.hp.value_or(0.),cap));const int percentage=std::clamp(int(std::round(100.*hp/cap)),0,100);const auto last=state.progress.find(name);if(last!=state.progress.end()&&last->second==percentage)continue;state.progress[name]=percentage;const auto extra=metadata.extra_indexes.find(name);if(extra==metadata.extra_indexes.end()||extra->second<=0)continue;out.push_back({name,extra->second,percentage,std::max(0.,seconds(name,repair,metadata.repair_speed_factor)*(1.-hp/cap)),false});}
 for(auto at=state.progress.begin();at!=state.progress.end();)if(!destroyed.count(at->first)){const auto extra=metadata.extra_indexes.find(at->first);if(extra!=metadata.extra_indexes.end()&&extra->second>0)out.push_back({at->first,extra->second,0,0.,true});at=state.progress.erase(at);}else ++at;
}
std::optional<V>report(const V&payload,State&state){if(state.base_revision<=0)return {};std::set<std::string>repaired;for(const auto&event:payload.get("events").resolved().array)if(event.get("kind").resolved().text=="device"&&track(event.get("name").resolved().text)&&event.get("old_state").resolved().text=="destroyed"&&event.get("state").resolved().text=="critical"&&event.get("cause").resolved().text=="repair")repaired.insert(event.get("name").resolved().text);std::set<std::string>destroyed;for(const auto&name:payload.get("destroyed").resolved().array)destroyed.insert(name.resolved().text);auto rows=array();for(const auto&raw:payload.get("devices").resolved().array){const auto name=raw.get("name").resolved().text,status=raw.get("state").resolved().text;if(!track(name)||(!destroyed.count(name)&&!repaired.count(name))||(status!="destroyed"&&status!="critical"))continue;const double hp=std::max(0.,raw.get("hp").numeric()),maximum=std::max(1.,raw.get("max_hp").numeric());if(status=="destroyed"&&hp<=.001)continue;auto value=object();value.object["name"]=text(name);value.object["hp"]=number(decimal(std::min(hp,maximum)));value.object["max_hp"]=number(decimal(maximum));value.object["state"]=text(status);rows.array.push_back(std::move(value));}if(rows.array.empty())return {};if(rows!=state.report.get("tracks"))++state.next_sequence;auto value=object();value.object["tracks"]=rows;value.object["critical_base_revision"]=integer(state.base_revision);value.object["critical_seq"]=integer(state.next_sequence);state.report=value;state.owned=true;return value;}
}
Owner::Owner(Metadata metadata,Critical critical,State state,std::set<std::string>casualties):metadata_(std::move(metadata)),state_(std::move(state)),tracks_(std::move(critical)),casualties_(std::move(casualties)){}
bool Owner::accept(std::int64_t revision,std::int64_t base,std::int64_t ack,Critical&canonical){revision=std::max<std::int64_t>(0,revision);base=std::max<std::int64_t>(0,base);ack=std::max<std::int64_t>(0,ack);if(have_revision_&&revision<state_.server_revision){mergeTracks(tracks_,canonical);return false;}const bool newer=!have_revision_||revision>state_.server_revision;const auto pending=state_.report;bool acknowledged=false;
 state_.server_revision=revision;if(base!=state_.base_revision){state_.base_revision=base;state_.next_sequence=0;state_.owned=false;state_.report=V{};}else if(pending.resolved().kind!=V::Kind::Null&&ack>=std::int64_t(pending.get("critical_seq").numeric())){bool complete=!pending.get("tracks").resolved().array.empty();for(const auto&row:pending.get("tracks").resolved().array)complete=complete&&row.get("state").resolved().text=="critical";state_.report=V{};state_.owned=!complete;acknowledged=true;}
 if(acknowledged&&state_.owned&&pending.resolved().kind!=V::Kind::Null){bool functional=!pending.get("tracks").resolved().array.empty();for(const auto&row:pending.get("tracks").resolved().array){const auto found=canonical.devices.find(row.get("name").resolved().text);functional=functional&&found!=canonical.devices.end()&&!found->second.destroyed&&(deviceState(found->second)=="normal"||deviceState(found->second)=="critical");}if(functional)state_.owned=false;}
 if(!newer||state_.owned)mergeTracks(tracks_,canonical);tracks_=canonical;have_revision_=true;return newer;
}
void Owner::reconcile(const shared::Actor&actor,Critical&canonical){const auto&state=actor.state;for(const char*name:{"critical_revision","critical_base_revision","critical_ack_seq"})if(state.get(name).resolved().kind==V::Kind::Null){if(have_revision_)mergeTracks(tracks_,canonical);else tracks_=canonical;return;}accept(std::int64_t(state.get("critical_revision").numeric()),std::int64_t(state.get("critical_base_revision").numeric()),std::int64_t(state.get("critical_ack_seq").numeric()),canonical);}
Effects Owner::advance(Critical current,double dt,double now,bool eligible,double repair,const std::set<std::string>&casualties){Effects out;if(dt<=0.||!eligible)return out;casualties_=casualties;const auto before=current;bool changed=false;for(const char*name:{"leftTrackHealth","rightTrackHealth"}){const auto at=current.devices.find(name);if(at==current.devices.end()||!at->second.destroyed||!at->second.hp)continue;const auto cap=metadata_.regeneration.find(name);if(cap==metadata_.regeneration.end())continue;auto&d=at->second;if(*d.hp>=cap->second){d.destroyed=false;d.critical=true;changed=true;continue;}const double repaired=std::min(cap->second,*d.hp+cap->second/std::max(.1,seconds(name,repair,metadata_.repair_speed_factor))*dt);if(repaired<=*d.hp)continue;d.hp=repaired;changed=true;if(repaired>=cap->second){d.destroyed=false;d.critical=true;}}
 tracks_=current;progress(current,metadata_,repair,state_,out.progress);if(changed){out.payload=payload(before,current,metadata_,casualties_);if(!out.payload->get("events").resolved().array.empty()||now>=state_.next_report_time){out.report=report(*out.payload,state_);state_.next_report_time=now+metadata_.network_seconds;}}return out;
}
}
